(function(){'use strict';let registration=null,waiting=null,accepting=false,newVersion=null,busy=false;const CURRENT=window.PC_RELEASE?.version||'0.3.0';const native=/PocketCritters(Android|iOS)/.test(navigator.userAgent);
let notice=document.createElement('div');notice.className='update-banner';notice.hidden=true;notice.innerHTML='<span><b>새로운 전장이 준비됐어요.</b><small>전투를 멈춘 뒤 최신 버전으로 이동합니다.</small></span><button>업데이트</button>';document.body.append(notice);
function safe(){return !document.body.classList.contains('playing')||!document.getElementById('modalShade')?.hidden}
function display(){if((waiting||newVersion)&&safe())notice.hidden=false;else notice.hidden=true}
notice.querySelector('button').onclick=()=>{window.dispatchEvent(new CustomEvent('pc:external-pause'));if(!safe())return;if(!confirm('저장된 턴을 유지하고 게임을 업데이트할까요? 진행 중 포격은 최근 저장 턴으로 돌아갑니다.'))return;accepting=true;if(waiting)waiting.postMessage({type:'APPLY_UPDATE'});else location.reload()};
async function check(){if(busy||document.hidden||location.protocol==='file:')return;busy=true;try{if(registration)await registration.update();let r=await fetch('/api/version',{cache:'no-store'});if(!r.ok)throw Error();let b=await r.json();if(typeof b.version==='string'&&b.version!==CURRENT)newVersion=b.version;}catch{}finally{busy=false;display()}}
if('serviceWorker'in navigator&&location.protocol!=='file:'&&!native){navigator.serviceWorker.register('./sw.js',{updateViaCache:'none'}).then(r=>{registration=r;if(r.waiting){waiting=r.waiting;display()}r.addEventListener('updatefound',()=>{let w=r.installing;w?.addEventListener('statechange',()=>{if(w.state==='installed'&&navigator.serviceWorker.controller){waiting=w;display()}})});check()}).catch(()=>{});navigator.serviceWorker.addEventListener('controllerchange',()=>{if(accepting)location.reload()})}
document.addEventListener('visibilitychange',()=>{if(!document.hidden)check()});window.addEventListener('online',check);setInterval(check,180000);setInterval(display,1000);if(native)check();
})();
